-- 2026-11-12-wardogs-economy-article-season3-havoc-update.sql
-- Brief 372. feed_items 213b32e2-44a1-4f10-8426-7b72777efa73 (wardogs-economy, published). Two guarded UPDATEs, run in order, each alone:
--   UPDATE 1 inserts one dated Season 3 paragraph between the Season 2 update paragraph and the Sources paragraph.
--   UPDATE 2 adds the Season 03 notes to the Sources paragraph (after the Season 02 notes entry) and to verified_source.
-- Source: Bulkhead's WARDOGS Season 03 patch notes (Steam news, November 11, 2026), https://store.steampowered.com/news/app/1867240/view/688648135317127221
-- NOT RUN by the executor. The operator runs each statement alone in the Supabase SQL editor: BEFORE, UPDATE 1, UPDATE 2, VERIFY.
-- One statement per line. Newlines are chr(10) and semicolons inside text are chr(59), so no quoted string holds a semicolon. No dollar quotes. LF, ASCII.
-- Only body, verified_source and updated_at change. verified_source_url (the Season 02 URL), created_at, headline and every other column are untouched.
-- updated_at = now() is set explicitly (the live set_updated_at BEFORE UPDATE trigger also fires on a body change).

-- BEFORE: run this alone. Expect body_chars 7930, body_md5 90e64201680fc9261905abab92f1b86d, body_cr_pos 0, s3_para_pos 0, vs_md5 49cf49d6e3ea0e187e71ac773bc3a45b.
SELECT id, slug, is_published, char_length(body) AS body_chars, md5(body) AS body_md5, position(chr(13) in body) AS body_cr_pos, position('Update (November 12, 2026)' in body) AS s3_para_pos, md5(verified_source) AS vs_md5, updated_at, verified_source, right(body, 600) AS body_tail FROM feed_items WHERE id = '213b32e2-44a1-4f10-8426-7b72777efa73';

-- UPDATE 1: run alone. Expect UPDATE 1. Guard: id, game_slug, is_published, the current length and md5, no carriage return.
UPDATE feed_items SET body = replace(body, ' opens later in Season 2.' || chr(10) || '' || chr(10) || 'Sources:', ' opens later in Season 2.' || chr(10) || '' || chr(10) || 'Update (November 12, 2026): Season 3, per Bulkhead''s Season 03 patch notes (posted November 11), lowers the Havoc from $28,000 to $26,000 and also lowers the Wolf-110 M2 Browning, Kodiak M249 and AH-6M Minigun prices. The Wager Vendor is removed and goes back into development, and the losing-faction vendor discount is now measured against the first-place faction instead of the faction above it. The first Early Access price increase is $5 and comes at the end of Season 3, so the stepped box prices in the pricing paragraph above predate it. The Season 2 update above is left as written for the record.' || chr(10) || '' || chr(10) || 'Sources:'), updated_at = now() WHERE id = '213b32e2-44a1-4f10-8426-7b72777efa73' AND game_slug = 'wardogs' AND is_published = true AND char_length(body) = 7930 AND md5(body) = '90e64201680fc9261905abab92f1b86d' AND position(chr(13) in body) = 0;

-- UPDATE 2: run alone, after UPDATE 1. Expect UPDATE 1. Guard: the body exactly as UPDATE 1 leaves it (8537 chars, md5 0ea9aa280f26762c10fb80f494efa1b9) and the current verified_source md5.
UPDATE feed_items SET body = replace(body, 'https://store.steampowered.com/news/app/1867240/view/670630562731396445' || chr(59) || ' WARDOGS - Supporter Pack', 'https://store.steampowered.com/news/app/1867240/view/670630562731396445' || chr(59) || ' Bulkhead, WARDOGS | Season 03 Patch Notes (Steam news, November 11, 2026), https://store.steampowered.com/news/app/1867240/view/688648135317127221' || chr(59) || ' WARDOGS - Supporter Pack'), verified_source = verified_source || '' || chr(59) || ' Bulkhead WARDOGS | Season 03 Patch Notes (Steam, 2026-11-11)', updated_at = now() WHERE id = '213b32e2-44a1-4f10-8426-7b72777efa73' AND game_slug = 'wardogs' AND is_published = true AND char_length(body) = 8537 AND md5(body) = '0ea9aa280f26762c10fb80f494efa1b9' AND md5(verified_source) = '49cf49d6e3ea0e187e71ac773bc3a45b';

-- VERIFY: run alone. Expect body_chars 8685, body_md5 681f4c5ed0993bfd87778edfd0786742, body_cr_pos 0, s3_para_pos 7227, vs_md5 8a4249e60b9cc2f5bcc49ea6dc0d017a, updated_at moved.
SELECT id, slug, is_published, char_length(body) AS body_chars, md5(body) AS body_md5, position(chr(13) in body) AS body_cr_pos, position('Update (November 12, 2026)' in body) AS s3_para_pos, md5(verified_source) AS vs_md5, updated_at, verified_source, right(body, 600) AS body_tail FROM feed_items WHERE id = '213b32e2-44a1-4f10-8426-7b72777efa73';

